export type SafeToolPresenceArgumentKey = Extract<
	SafeToolArgumentKey,
	| "date"
	| "end_date"
	| "exercise_template_id"
	| "folder_id"
	| "primary_muscle_group"
	| "query"
	| "routine_id"
	| "since"
	| "start_date"
	| "updated_since"
	| "workout_id"
>;

export type SafeToolNumericArgumentKey = Extract<
	SafeToolArgumentKey,
	"limit" | "offset" | "page" | "page_size"
>;

export type SafeToolBooleanArgumentKey = Extract<
	SafeToolArgumentKey,
	"include_custom" | "refresh"
>;

export interface ToolInvocationObservation {
	readonly name: string;
	/** The MCP primitive being observed; omitted values remain tool-compatible. */
	readonly kind?: "tool" | "prompt";
	readonly taxonomy?: ToolTelemetryMetadata;
	readonly argumentKeys?: readonly SafeToolArgumentKey[];
	readonly argumentPresence?: Partial<
		Readonly<Record<SafeToolPresenceArgumentKey, true>>
	>;
	readonly numericArgumentBuckets?: Partial<
		Readonly<Record<SafeToolNumericArgumentKey, ResultCountBucket>>
	>;
	readonly booleanArguments?: Partial<
		Readonly<Record<SafeToolBooleanArgumentKey, boolean>>
	>;
	readonly argumentKeyCountBucket?: ResultCountBucket;
}

export interface ToolResultObservation {
	readonly isError: boolean;
	readonly hasStructuredContent: boolean;
	readonly contentCountBucket: ResultCountBucket;
	readonly summary?: ToolResultTelemetry;
}

export interface ToolCompletionObservation {
	readonly outcome: "success" | "returned_error" | "thrown_error";
	readonly durationMs: number;
	readonly result?: ToolResultObservation;
	readonly errorType?: ErrorType;
	readonly error?: SafeErrorDiagnostic;
	readonly errorOutcome?: StructuredExecutionProjection;
}

export interface ToolObservationScope {
	run<T>(operation: () => Promise<T>): Promise<T>;
	finish(completion: ToolCompletionObservation): void | Promise<void>;
}

export interface ToolObserver {
	start(invocation: ToolInvocationObservation): ToolObservationScope | void;
}

export type SafeToolInvocation = ToolInvocationObservation;
export type SafeToolCompletion = ToolCompletionObservation;

export function memoizeObservationScope(
	scope: ToolObservationScope | void,
): ToolObservationScope | undefined {
	if (!scope) return undefined;
	let finished = false;
	let operationPromise: Promise<unknown> | undefined;
	return {
		run<T>(operation: () => Promise<T>): Promise<T> {
			if (!operationPromise) {
				try {
					operationPromise = Promise.resolve(scope.run(operation));
				} catch (error) {
					operationPromise = Promise.reject(error);
				}
			}
			return operationPromise as Promise<T>;
		},
		finish(completion) {
			if (finished) return;
			finished = true;
			try {
				const pending = scope.finish(completion);
				if (pending) void pending.catch(() => undefined);
			} catch {
				// Observation must never alter MCP behavior.
			}
		},
	};
}
import { McpServer } from "@modelcontextprotocol/server";
import type { HevyClient, HevyClientLogEvent } from "@hevy-mcp/hevy-client";
import { registerWorkoutPrompts } from "./prompts/workouts.js";
import { registerHevyResources } from "./resources/hevy.js";
import {
	SERVER_INSTRUCTIONS,
	SERVER_NAME,
	SERVER_VERSION,
} from "./server-metadata.js";
import { registerHevyTools } from "./tools/register.js";
import { createToolRuntime } from "./tools/tool-runtime.js";
import { createExerciseTemplateCatalog } from "./utils/exercise-template-catalog.js";
import { createMcpClientLogger } from "./utils/mcp-client-logger.js";
import type { CacheObserver } from "./utils/cache.js";
import type { ToolObserver } from "./observation.js";
export interface HevyClientFactoryContext {
	readonly onLog: (event: HevyClientLogEvent) => void;
}

export interface CreateHevyMcpServerOptions {
	readonly createClient: (context: HevyClientFactoryContext) => HevyClient;
	readonly observer?: ToolObserver;
	readonly cacheObserver?: CacheObserver;
	readonly decorateServer?: (server: McpServer) => McpServer;
	readonly onToolsRegistered?: (count: number) => void;
	/** One absolute budget for each incoming MCP invocation. */
	readonly executionTimeoutMs?: number;
	/** Absolute deadline shared by validation and every tool call in one invocation. */
	readonly executionDeadline?: number;
	readonly lifecycleSignal?: AbortSignal;
}

function createCountingServer(server: McpServer) {
	let count = 0;
	const countingServer = new Proxy(server, {
		get(target, property, receiver) {
			if (property === "registerTool") {
				const registerTool = target.registerTool.bind(target);
				return (...args: unknown[]) => {
					const result = Reflect.apply(registerTool, target, args);
					count += 1;
					return result;
				};
			}
			return Reflect.get(target, property, receiver);
		},
	});
	return { server: countingServer, getCount: () => count };
}

export function createHevyMcpServer(
	options: CreateHevyMcpServerOptions,
): McpServer {
	const baseServer = new McpServer(
		{ name: SERVER_NAME, version: SERVER_VERSION },
		{ capabilities: { logging: {} }, instructions: SERVER_INSTRUCTIONS },
	);
	const server = options.decorateServer?.(baseServer) ?? baseServer;
	const mcpLogger = createMcpClientLogger(server);
	const client = options.createClient({ onLog: (event) => mcpLogger(event) });
	const runtime = createToolRuntime({
		client,
		catalog: createExerciseTemplateCatalog(client, options.cacheObserver),
		logger: mcpLogger,
		observer: options.observer,
		executionTimeoutMs: options.executionTimeoutMs,
		executionDeadline: options.executionDeadline,
		lifecycleSignal: options.lifecycleSignal,
	});
	const counting = createCountingServer(server);
	registerHevyTools(counting.server, runtime);
	options.onToolsRegistered?.(counting.getCount());
	registerWorkoutPrompts(server, options.observer);
	registerHevyResources(server, runtime);
	return server;
}
