g-border hover:bg-accent hover:ring-border-strong h-10 gap-2 px-4 text-sm rounded-lg" target="_blank" aria-label="Subscribe to the changelog RSS feed"><svg width="1em" height="1em" class="h-4 w-4" data-icon="ph:rss-simple"><symbol id="ai:ph:rss-simple" viewBox="0 0 256 256"><path fill="currentColor" d="M224 192a8 8 0 0 1-16 0c0-79.4-64.6-144-144-144a8 8 0 0 1 0-16c88.22 0 160 71.78 160 160M64 104a8 8 0 0 0 0 16a72.08 72.08 0 0 1 72 72a8 8 0 0 0 16 0a88.1 88.1 0 0 0-88-88m4 72a12 12 0 1 0 12 12a12 12 0 0 0-12-12"/></symbol><use href="#ai:ph:rss-simple"></use></svg>Subscribe to RSS</a></div></div><script type="module">function e(){document.querySelectorAll(`[data-changelog-product-nav]`).forEach(e=>{e.dataset.navBound||(e.dataset.navBound=`1`,e.addEventListener(`combobox:change`,e=>{let{value:t}=e.detail;t&&t!==window.location.pathname&&(window.location.href=t)}))})}document.addEventListener(`DOMContentLoaded`,e),document.addEventListener(`astro:page-load`,e),e();</script><div class="md:px-14 lg:px-16"><a href="/changelog" class="group text-muted-foreground hover:text-foreground mb-9 -ml-0.5 inline-flex items-center gap-1.5 text-[0.8125rem] font-medium no-underline transition-[color,transform] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] active:scale-[0.98] motion-reduce:active:scale-100"><svg width="1em" height="1em" class="h-4 w-4 transition-transform duration-[160ms] ease-[cubic-bezier(0.23,1,0.32,1)] group-hover:-translate-x-0.5 motion-reduce:transform-none" data-icon="ph:arrow-left"><symbol id="ai:ph:arrow-left" viewBox="0 0 256 256"><path fill="currentColor" d="M224 128a8 8 0 0 1-8 8H59.31l58.35 58.34a8 8 0 0 1-11.32 11.32l-72-72a8 8 0 0 1 0-11.32l72-72a8 8 0 0 1 11.32 11.32L59.31 120H216a8 8 0 0 1 8 8"/></symbol><use href="#ai:ph:arrow-left"></use></svg><span>Back to all posts</span></a><article><time datetime="2026-06-16" class="text-muted-foreground block text-[0.8125rem] font-medium tabular-nums">June 16, 2026</time><h2 class="text-foreground mt-2 mb-0 leading-[1.15] text-balance" style="font-size:var(--nb-h1-size);font-weight:var(--nb-h1-weight);letter-spacing:var(--nb-h1-tracking)">Workers tracing now supports custom spans</h2><div class="mt-4"><div class="flex flex-row flex-wrap gap-2"><a href="/workers/" class="no-underline"><span class="inline-flex items-center rounded-full font-medium whitespace-nowrap bg-success-muted text-success px-2 py-0.5 text-xs">Workers</span></a></div></div><div class="docs-content nb-cl-prose mt-9 max-w-none"><p>You can now create custom trace spans in your Workers code using <code>tracing.enterSpan()</code>. Custom spans appear alongside the automatic platform instrumentation (fetch calls, KV reads, D1 queries, and other platform operations) in your traces and OpenTelemetry exports, with correct parent-child nesting.</p>
<p>The API is available via <code>import { tracing } from "cloudflare:workers"</code> or through the handler context as <code>ctx.tracing</code>:</p>
<figure class="nb-code-figure" data-nb-lang="ts"><pre class="astro-code astro-code-themes github-light github-dark nb-shiki-c6xiwz" tabindex="0" data-language="ts" data-nb-lang="ts"><code><span class="line"><span class="nb-shiki-1itgoe">import</span><span class="nb-shiki-140thh"> { tracing } </span><span class="nb-shiki-1itgoe">from</span><span class="nb-shiki-mdbnqw"> "cloudflare:workers"</span><span class="nb-shiki-140thh">;</span></span>
<span class="line"></span>
<span class="line"><span class="nb-shiki-1itgoe">export</span><span class="nb-shiki-1itgoe"> default</span><span class="nb-shiki-140thh"> {</span></span>
<span class="line"><span class="nb-shiki-1itgoe">  async</span><span class="nb-shiki-1t8gfj"> fetch</span><span class="nb-shiki-140thh">(</span><span class="nb-shiki-1jdh33">request</span><span class="nb-shiki-140thh">, </span><span class="nb-shiki-1jdh33">env</span><span class="nb-shiki-140thh">, </span><span class="nb-shiki-1jdh33">ctx</span><span class="nb-shiki-140thh">) {</span></span>
<span class="line"><span class="nb-shiki-1itgoe">    return</span><span class="nb-shiki-140thh"> tracing.</span><span class="nb-shiki-1t8gfj">enterSpan</span><span class="nb-shiki-140thh">(</span><span class="nb-shiki-mdbnqw">"handleRequest"</span><span class="nb-shiki-140thh">, </span><span class="nb-shiki-1itgoe">async</span><span class="nb-shiki-140thh"> (</span><span class="nb-shiki-1jdh33">span</span><span class="nb-shiki-140thh">) </span><span class="nb-shiki-1itgoe">=&gt;</span><span class="nb-shiki-140thh"> {</span></span>
<span class="line"><span class="nb-shiki-140thh">      span.</span><span class="nb-shiki-1t8gfj">setAttribute</span><span class="nb-shiki-140thh">(</span><span class="nb-shiki-mdbnqw">"url.path"</span><span class="nb-shiki-140thh">, </span><span class="nb-shiki-1itgoe">new</span><span class="nb-shiki-1t8gfj"> URL</span><span class="nb-shiki-140thh">(request.url).pathname);</span></span>
<span class="line"><span class="nb-shiki-1itgoe">      const</span><span class="nb-shiki-dzsirb"> data</span><span class="nb-shiki-1itgoe"> =</span><span class="nb-shiki-1itgoe"> await</span><span class="nb-shiki-140thh"> env.</span><span class="nb-shiki-dzsirb">MY_KV</span><span class="nb-shiki-140thh">.</span><span class="nb-shiki-1t8gfj">get</span><span class="nb-shiki-140thh">(</span><span class="nb-shiki-mdbnqw">"key"</span><span class="nb-shiki-140thh">);</span></span>
<span class="line"><span class="nb-shiki-1itgoe">      return</span><span class="nb-shiki-1itgoe"> new</span><span class="nb-shiki-1t8gfj"> Response</span><span class="nb-shiki-140thh">(data);</span></span>
<span class="line"><span class="nb-shiki-140thh">    });</span></span>
<span class="line"><span class="nb-shiki-140thh">  },</span></span>
<span class="line"><span class="nb-shiki-140thh">};</span></span></code></pre></figure>
<p>Spans nest automatically based on the JavaScript async context, and are auto-ended when the callback returns or its returned promise settles. The <code>Span</code> object provides <code>setAttribute(key, value)</code> for attaching metadata and an <code>isTraced</code> property to check whether the current request is being sampled.</p>
<img src="/cdn-cgi/image/onerror=redirect,width=1988,height=670,format=webp/_astro/wobs_custom_spans_screenshot.B-hsHjyv.png" alt="Trace waterfall showing custom spans nested alongside automatic KV and fetch instrumentation" loading="lazy" decoding="async" width="1988" height="670">
<p><a href="/workers/observability/traces/#how-to-enable-tracing">Tracing must be enabled</a> in your Wrangler configuration for spans to be recorded.</p>
<p>For full API details and examples, refer to <a href="/workers/observability/traces/custom-spans/">Custom spans</a>.</p></div></article></div></div></div></main></div><footer class="nb-footer z-10 w-full overflow-x-clip px-px" data-astro-cid-jo6i4kqk><svg class="block h-px w-full relative left-1/2 w-screen -translate-x-1/2" preserveAspectRatio="none" aria-hidden="true"><line x1="0" y1="0.5" x2="100%" y2="0.5" stroke="var(--nb-border)" stroke-width="1" stroke-dasharray="16,16"></line></svg><div class="footer-scroll-host bg-background-100 px-section relative mx-auto flex w-full flex-col justify-between overflow-visible bg-linear-to-b pt-8 select-none [@media(max-height:924px)]:min-h-screen" data-astro-cid-jo6i4kqk><div class="pointer-events-none relative mx-auto flex h-full w-full max-w-[1480px] flex-col items-start gap-8 pb-8 lg:justify-between" data-astro-cid-jo6i4kqk><div class="flex justify-start lg:block lg:justify-center" data-astro-cid-jo6i4kqk><div class="flex flex-col items-start justify-start transition-opacity duration-200 ease-out lg:flex-row" data-astro-cid-jo6i4kqk><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 719 59" fill="none" class="footer-cf-wordmark text-foreground-200 h-[12px] w-auto" aria-label="Cloudflare wordmark" role="img" data-astro-cid-jo6i4kqk="true"><path d="M77.1016 1.09961H92.7015V43.5996H119.802V57.1996H77.1016V1.09961Z" fill="currentColor"></path><path d="M135.898 29.3V29.2C135.898 13.1 148.898 0 166.198 0C183.498 0 196.298 12.9 196.298 29V29.2C196.298 45.3 183.298 58.4 165.998 58.4C148.798 58.3 135.898 45.4 135.898 29.3ZM180.498 29.3V29.2C180.498 21.1 174.698 14.1 166.098 14.1C157.598 14.1 151.898 21 151.898 29.1V29.3C151.898 37.4 157.698 44.4 166.198 44.4C174.798 44.3 180.498 37.4 180.498 29.3Z" fill="currentColor"></path><path d="M215.398 32.5996V1.09961H231.198V32.2996C231.198 40.3996 235.298 44.1996 241.498 44.1996C247.698 44.1996 251.798 40.4996 251.798 32.6996V1.09961H267.598V32.1996C267.598 50.2996 257.298 58.1996 241