		npmCommand,
		[
			"exec",
			"--",
			"wrangler",
			"dev",
			"--config",
			"wrangler.test.jsonc",
			"--local",
			"--ip",
			LOOPBACK,
			"--port",
			String(workerPort),
			"--inspector-ip",
			LOOPBACK,
			"--inspector-port",
			String(inspectorPort),
			"--local-protocol",
			"http",
			"--show-interactive-dev-session=false",
			"--log-level",
			"warn",
			"--var",
			`HEVY_API_BASE_URL:${fakeHevyBaseUrl}`,
		],
		{
