    if (ts.isTypeAliasDeclaration(n) && ['HevyToolDefinition','HevyToolName','DefinitionByName','InputShapeFor','HevyToolArguments','DebugName','DebugArguments'].includes(n.name.text)) {
      const t=checker.getTypeFromTypeNode(n.type);
